// Data filtering and validation logic
const data = msg.payload;

// Validate data structure
if (!data.device_id || !data.timestamp) {
    node.warn('Invalid data structure received');
    return null;
}

// Filter outliers based on reasonable ranges
const filteredData = {
    device_id: data.device_id,
    timestamp: data.timestamp,
    soil_moisture: Math.max(0, Math.min(100, data.soil_moisture)),
    temperature: Math.max(-10, Math.min(50, data.temperature)),
    humidity: Math.max(0, Math.min(100, data.humidity)),
    light: Math.max(0, Math.min(2000, data.light))
};

// Check for significant changes (outlier detection)
const lastData = global.get('lastSensorData') || {};
if (lastData.device_id === data.device_id) {
    const soilChange = Math.abs(filteredData.soil_moisture - lastData.soil_moisture);
    const tempChange = Math.abs(filteredData.temperature - lastData.temperature);

    // If change is too dramatic, use previous value with small adjustment
    if (soilChange > 20) {
        filteredData.soil_moisture = lastData.soil_moisture + (soilChange > 0 ? 5 : -5);
    }
    if (tempChange > 10) {
        filteredData.temperature = lastData.temperature + (tempChange > 0 ? 2 : -2);
    }
}

// Store for next comparison
global.set('lastSensorData', filteredData);

// Add processing metadata
filteredData.processed_at = new Date().toISOString();
filteredData.data_quality = 'good';

msg.payload = filteredData;
return msg;

// Decision engine for irrigation and fertilization
const data = msg.payload;
const decisions = [];

// Irrigation decision based on soil moisture
if (data.soil_moisture < 30) {
    decisions.push({
        action: 'irrigate',
        duration: Math.min(600, (30 - data.soil_moisture) * 20), // Max 10 minutes
        priority: 'high',
        reason: 'Low soil moisture detected'
    });
} else if (data.soil_moisture > 80) {
    decisions.push({
        action: 'drain',
        duration: 300,
        priority: 'medium',
        reason: 'High soil moisture detected'
    });
}

// Fertilization decision based on temperature and humidity
if (data.temperature > 20 && data.temperature < 30 && data.humidity > 40 && data.humidity < 80) {
    const daysSinceLastFertilizer = global.get('lastFertilizerDate') || 0;
    const daysDiff = (Date.now() - daysSinceLastFertilizer) / (1000 * 60 * 60 * 24);

    if (daysDiff > 7) { // Fertilize every 7 days
        decisions.push({
            action: 'fertilize',
            amount: 50, // ml
            priority: 'medium',
            reason: 'Optimal conditions for fertilization'
        });
        global.set('lastFertilizerDate', Date.now());
    }
}

// Light-based decisions
if (data.light < 200) {
    decisions.push({
        action: 'alert',
        message: 'Low light conditions detected',
        priority: 'low',
        reason: 'Insufficient light for optimal growth'
    });
}

// Temperature alerts
if (data.temperature < 5 || data.temperature > 40) {
    decisions.push({
        action: 'alert',
        message: 'Extreme temperature detected',
        priority: 'high',
        reason: `Temperature ${data.temperature}°C is outside safe range`
    });
}

msg.payload = {
    sensor_data: data,
    decisions: decisions,
    timestamp: new Date().toISOString()
};

return msg;

// Control irrigation and other actuators
const data = msg.payload;
const decisions = data.decisions;

for (const decision of decisions) {
    if (decision.action === 'irrigate') {
        // Send irrigation command
        const irrigationMsg = {
            topic: 'actuators/irrigation',
            payload: {
                action: 'start',
                duration: decision.duration,
                device_id: data.sensor_data.device_id,
                timestamp: new Date().toISOString()
            }
        };
        node.send(irrigationMsg);
    } else if (decision.action === 'fertilize') {
        // Send fertilization command
        const fertilizerMsg = {
            topic: 'actuators/fertilizer',
            payload: {
                action: 'dispense',
                amount: decision.amount,
                device_id: data.sensor_data.device_id,
                timestamp: new Date().toISOString()
            }
        };
        node.send(fertilizerMsg);
    }
}

return msg;

// Check for alert conditions
const data = msg.payload;
const alerts = [];

// Critical alerts
if (data.soil_moisture < 15) {
    alerts.push({
        type: 'critical',
        message: 'Critical: Soil moisture extremely low',
        value: data.soil_moisture,
        threshold: 15
    });
}

if (data.temperature > 35) {
    alerts.push({
        type: 'critical',
        message: 'Critical: High temperature detected',
        value: data.temperature,
        threshold: 35
    });
}

// Warning alerts
if (data.humidity < 30) {
    alerts.push({
        type: 'warning',
        message: 'Warning: Low humidity',
        value: data.humidity,
        threshold: 30
    });
}

if (data.light < 100) {
    alerts.push({
        type: 'warning',
        message: 'Warning: Insufficient light',
        value: data.light,
        threshold: 100
    });
}

if (alerts.length > 0) {
    msg.payload = {
        alerts: alerts,
        sensor_data: data,
        timestamp: new Date().toISOString()
    };
    return msg;
}

return null;

// Send notifications for alerts
const data = msg.payload;
const alerts = data.alerts;

for (const alert of alerts) {
    // Send to notification service
    const notificationMsg = {
        topic: 'notifications/alert',
        payload: {
            type: alert.type,
            message: alert.message,
            value: alert.value,
            threshold: alert.threshold,
            device_id: data.sensor_data.device_id,
            timestamp: new Date().toISOString()
        }
    };
    node.send(notificationMsg);
}

return msg;
